def minimize_debts(n, debts):
    from collections import defaultdict

    # Calculate net debts for each person
    net_debts = defaultdict(int)
    for a, b, c in debts:
        net_debts[a] += c
        net_debts[b] -= c

    # Filter out people with zero net debt
    non_zero_debts = [amount for amount in net_debts.values() if amount != 0]

    def dfs(start, non_zero_debts):
        if start == len(non_zero_debts):
            return 0
        if non_zero_debts[start] == 0:
            return dfs(start + 1, non_zero_debts)
        min_debt = float('inf')
        for i in range(start + 1, len(non_zero_debts)):
            if non_zero_debts[start] * non_zero_debts[i] < 0:
                # Try to settle debts between start and i
                non_zero_debts[i] += non_zero_debts[start]
                min_debt = min(min_debt, abs(non_zero_debts[start]) + dfs(start + 1, non_zero_debts))
                # Backtrack
                non_zero_debts[i] -= non_zero_debts[start]
        return min_debt

    return dfs(0, non_zero_debts)

