def optimize_debts(n, debts):
    balance = [0] * (n + 1)
    graph = defaultdict(list)

    for a, b, c in debts:
        balance[a] -= c
        balance[b] += c
        graph[a].append((b, c))

    def dfs(node):
        if node == n + 1:
            return 0

        total = dfs(node + 1)

        if balance[node] > 0:
            for next_node in range(node + 1, n + 1):
                if balance[next_node] < 0:
                    amount = min(balance[node], -balance[next_node])
                    balance[node] -= amount
                    balance[next_node] += amount
                    total = min(total, amount + dfs(node))
                    balance[node] += amount
                    balance[next_node] -= amount

        return total

