from collections import defaultdict
from itertools import combinations

def minimize_debts(n, debts):
    # Create a graph of debts
    graph = defaultdict(int)
    for a, b, amount in debts:
        graph[a] -= amount
        graph[b] += amount

    # Create a list of net balances
    balances = [balance for balance in graph.values() if balance != 0]

    # Helper function to recursively solve the problem
    def solve(balances):
        if not balances:
            return 0
        if balances[0] == 0:
            return solve(balances[1:])

        min_debt = float('inf')
        for i in range(1, len(balances)):
            if balances[i] * balances[0] < 0:
                new_balances = balances[1:]
                new_balances[i] += balances[0]
                min_debt = min(min_debt, abs(balances[0]) + solve(new_balances))

        return min_debt

    return solve(balances)

